// Capture each finger independently. A thumb can slide between direction buttons
// without lifting; it stops moving on leaving the direction cluster. Jump remains
// a deliberate press, so swiping across it can never trigger an accidental hop.
function syncPointerDirections(){
 const held=[...pointers.values()];
 for(const c of ['left','right']){
  controls[c]=held.includes(c)||[...heldKeys].some(k=>({ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'})[k]===c);
  app.querySelector(`[data-control=${c}]`).classList.toggle('pressed',controls[c]);
 }
}
$$('[data-control]').forEach(el=>{
 el.addEventListener('pointerdown',e=>{
  e.preventDefault();if(screen!=='game'||dialog)return;
  const c=el.dataset.control;pointers.set(e.pointerId,c);el.setPointerCapture(e.pointerId);
  if(c==='jump'){tapJump();el.classList.add('pressed')}else syncPointerDirections();
 });
 el.addEventListener('pointermove',e=>{
  const prior=pointers.get(e.pointerId);
  if(prior!=='left'&&prior!=='right'&&prior!=='direction-out')return;
  const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-control]');
  const next=hit&&['left','right'].includes(hit.dataset.control)?hit.dataset.control:'direction-out';
  if(prior!==next){pointers.set(e.pointerId,next);syncPointerDirections()}
 });
 const end=e=>{
  const c=pointers.get(e.pointerId);if(!c)return;pointers.delete(e.pointerId);
  if(c==='jump'&&!([...pointers.values()].includes('jump'))){releaseJump();app.querySelector('[data-control=jump]').classList.remove('pressed')}
  else if(c!=='jump')syncPointerDirections();
 };
 el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('lostpointercapture',end);
});
